import json
from pathlib import Path

drafts = {}

def add(number, paragraphs, reason, notes):
    assert number not in drafts
    drafts[number] = {
        'proposed_xml': ''.join('<p>' + p + '</p>' for p in paragraphs),
        'reason': reason,
        'review_notes': notes,
        'status': 'rewrite_draft',
    }

